preset.customCSS:
@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-width: 0;
}
.risu-chat > div > div {
  width: 100%;
  min-width: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtmsa-font-size로 바꿉니다. */
.rtmsa {
  --rtmsa-bg-fill: transparent;
  --rtmsa-bg-border: 0;
  --rtmsa-blur: none;
  --rtmsa-bg-edge: none;
  --rtmsa-bg-sheen: linear-gradient(transparent, transparent);
  --rtmsa-bg-fallback: transparent;
  --rtmsa-font-body: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsa-font-display: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsa-font-size: 15.5px;
  --rtmsa-line-height: 1.7;
  --rtmsa-para-gap: .7em;
  --rtmsa-dialog-weight: 600;
  --rtmsa-avatar: clamp(2.65rem, 6vw, 3.25rem);
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtmsa {
  --risu-font-family: var(--rtmsa-font-body);
  --FontColorStandard: var(--rtmsa-ink);
  --FontColorBold: var(--rtmsa-strong, var(--rtmsa-ink));
  --FontColorItalic: var(--rtmsa-muted);
  --FontColorItalicBold: var(--rtmsa-muted);
  --FontColorQuote1: var(--rtmsa-muted);
  --FontColorQuote2: var(--rtmsa-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtmsa-ink);
  font-family: var(--rtmsa-font-body);
  font-size: var(--rtmsa-font-size);
  line-height: var(--rtmsa-line-height);
  letter-spacing: var(--rtmsa-tracking, -.005em);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.rtmsa, .rtmsa *, .rtmsa *::before, .rtmsa *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtmsa.rtmsa { display: block; }
.rtmsa ::selection { background: color-mix(in srgb, var(--rtmsa-accent) 26%, transparent); color: inherit; }
.rtmsa__content {
  min-width: 0;
  color: var(--rtmsa-ink);
  word-break: keep-all;
  overflow-wrap: break-word;
  text-wrap: pretty;
}
.rtmsa__content .chattext {
  --tw-prose-code: var(--rtmsa-strong, var(--rtmsa-ink));
  --tw-prose-pre-code: var(--rtmsa-ink);
  --tw-prose-pre-bg: var(--rtmsa-tint);
  max-width: none;
  color: var(--rtmsa-ink);
  font-size: var(--rtmsa-font-size) !important;
  line-height: var(--rtmsa-line-height) !important;
}
/* :where()로 우선순위를 낮춰 캐릭터 카드 자체 HTML 스타일이 이기게 합니다. */
.rtmsa__content :where(p, li, td, th, blockquote) {
  font-size: var(--rtmsa-font-size);
  line-height: var(--rtmsa-line-height);
}
.rtmsa__content :where(p) { margin: 0 0 var(--rtmsa-para-gap); }
.rtmsa__content :where(p:last-child) { margin-bottom: 0; }
.rtmsa__content :where(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtmsa-font-display);
  margin: 1.35em 0 .55em;
  color: var(--rtmsa-strong, var(--rtmsa-ink));
  font-family: var(--rtmsa-font-display);
  line-height: 1.35;
  letter-spacing: -.015em;
  font-weight: 700;
}
.rtmsa__content :where(h1, h2, h3, h4, h5, h6):where(:first-child) { margin-top: .15em; }
.rtmsa__content :where(h1) { font-size: calc(var(--rtmsa-font-size) * 1.55); }
.rtmsa__content :where(h2) { font-size: calc(var(--rtmsa-font-size) * 1.32); }
.rtmsa__content :where(h3) { font-size: calc(var(--rtmsa-font-size) * 1.15); }
.rtmsa__content :where(h4, h5, h6) { font-size: var(--rtmsa-font-size); color: var(--rtmsa-muted); }
.rtmsa__content :where(strong) { font-weight: 700; color: var(--rtmsa-strong, var(--rtmsa-ink)); }
/* 한글은 기울임 글꼴이 없어 가짜 기울임 대신 색으로만 구분합니다. */
.rtmsa__content :where(em) { font-style: normal; color: var(--rtmsa-muted); }
.rtmsa__content mark[risu-mark="quote1"],
.rtmsa__content mark[risu-mark="blockquote1"] { color: var(--rtmsa-muted); background: transparent; }
.rtmsa__content mark[risu-mark="quote2"],
.rtmsa__content mark[risu-mark="blockquote2"] {
  color: var(--rtmsa-dialog);
  font-weight: var(--rtmsa-dialog-weight);
  background: transparent;
}
.rtmsa__content :where(blockquote) {
  margin: 1em 0;
  padding: .55em 1.05em;
  border-left: 2.5px solid var(--rtmsa-accent);
  border-radius: 0 .5rem .5rem 0;
  background: var(--rtmsa-tint);
  color: var(--rtmsa-muted);
}
.rtmsa__content :where(ul, ol) { margin: .85em 0; padding-left: 1.45em; }
.rtmsa__content :where(li) { margin: .28em 0; padding-left: .12em; color: var(--rtmsa-ink); }
.rtmsa__content :where(li)::marker { color: var(--rtmsa-accent); }
.rtmsa__content :where(a) {
  color: var(--rtmsa-accent);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--rtmsa-accent) 45%, transparent);
  text-underline-offset: 3px;
}
.rtmsa__content :where(a:hover) { text-decoration-color: currentColor; }
.rtmsa__content :where(hr) {
  height: 1px;
  border: 0;
  margin: 1.55em 0;
  background: linear-gradient(90deg, transparent, var(--rtmsa-line) 15%, var(--rtmsa-line) 85%, transparent);
}
.rtmsa__content :where(code) {
  --risu-font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  padding: .12em .38em;
  border-radius: .3em;
  color: var(--rtmsa-strong, var(--rtmsa-ink));
  background: var(--rtmsa-tint);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtmsa-font-size) * .88);
  line-height: 1.5;
}
.rtmsa__content :where(pre) {
  max-width: 100%;
  overflow-x: auto;
  margin: 1em 0;
  padding: .9em 1.05em;
  color: var(--rtmsa-ink);
  background: var(--rtmsa-tint);
  border: 1px solid var(--rtmsa-line);
  border-radius: .5rem;
  font-size: calc(var(--rtmsa-font-size) * .88);
  line-height: 1.55;
}
.rtmsa__content :where(pre code) { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtmsa__content :where(table) {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtmsa__content :where(th, td) {
  padding: .52em .78em;
  color: var(--rtmsa-ink);
  border-bottom: 1px solid var(--rtmsa-line);
  text-align: left;
  vertical-align: top;
}
.rtmsa__content :where(th) {
  background: var(--rtmsa-tint);
  color: var(--rtmsa-strong, var(--rtmsa-ink));
  font-weight: 600;
}
.rtmsa__content :where(img) { display: block; max-width: 100%; height: auto; margin: .75em auto; border-radius: .55rem; }
.rtmsa__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 6rem;
  padding: .75rem .9rem;
  resize: vertical;
  color: var(--rtmsa-ink) !important;
  background: var(--rtmsa-edit-bg) !important;
  border: 1px solid var(--rtmsa-line);
  border-radius: .55rem;
  font: inherit;
  font-size: var(--rtmsa-font-size) !important;
  line-height: var(--rtmsa-line-height) !important;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.rtmsa__content textarea.message-edit-area:focus {
  outline: none;
  border-color: var(--rtmsa-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rtmsa-accent) 18%, transparent);
}

/* 조작부: 생성 정보와 Risu 기본 버튼만 다듬고, 서드파티 플러그인 버튼 모양은 유지합니다. */
.rtmsa__footer {
  /* RisuAI(Tailwind v4)는 버튼 색을 --color-textcolor2로 칠하고, 이 변수는 페이지 맨 위에서 이미 앱 설정 색으로 정해져 있습니다.
     --risu-theme-textcolor2만 바꾸면 버튼은 앱 색으로 남아 종이·어두운 바탕에서 보이지 않으므로, 버튼이 실제로 쓰는 변수를 여기서 다시 정합니다. */
  --risu-theme-textcolor2: var(--rtmsa-muted);
  --color-textcolor2: var(--rtmsa-muted);
  --color-textcolor: var(--rtmsa-ink);
  --color-darkborderc: var(--rtmsa-line);
  --color-darkbutton: var(--rtmsa-line);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtmsa-muted);
}
.rtmsa__info, .rtmsa__actions { min-width: 0; max-width: 100%; }
.rtmsa__info > div, .rtmsa__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; color: var(--rtmsa-muted); }
.rtmsa__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtmsa__info button.transition-all,
.rtmsa__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtmsa__info button.transition-all:hover,
.rtmsa__actions button[class*="button-icon-"]:hover { background: var(--rtmsa-tint); color: var(--rtmsa-ink); }
.rtmsa__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtmsa-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtmsa__info button:not(.transition-all):hover { background: var(--rtmsa-tint); color: var(--rtmsa-ink); }
.rtmsa :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtmsa-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtmsa__portrait { overflow: hidden; background: var(--rtmsa-tint); }
.rtmsa__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

@media (prefers-reduced-motion: reduce) {
  .rtmsa, .rtmsa * { transition: none !important; animation: none !important; }
}
@media (prefers-reduced-transparency: reduce) {
  .rtmsa .rtmsa__bg {
    background: var(--rtmsa-bg-fallback, var(--rtmsa-bg-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtmsa .rtmsa__bg { background: var(--rtmsa-bg-fallback, var(--rtmsa-bg-fill)); }
}

.rtmsa__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtmsa-bg-fill);
  border: var(--rtmsa-bg-border, 0);
  -webkit-backdrop-filter: var(--rtmsa-blur);
  backdrop-filter: var(--rtmsa-blur);
  box-shadow: var(--rtmsa-bg-edge);
}

/* 구조: 메신저 한쪽 */

.rtmsa { background: var(--rtmsa-wall); padding: .5rem clamp(.75rem, 3vw, 1.5rem); }
.rtmsa__row { display: flex; align-items: flex-start; gap: .65rem; max-width: 52rem; margin: 0 auto; }
.rtmsa__avatar { flex: 0 0 auto; width: var(--rtmsa-avatar); aspect-ratio: 1; }
.rtmsa__portrait {
  width: 100%;
  height: 100%;
  padding: 2px;
  border-radius: 50%;
  background: linear-gradient(145deg, var(--rtmsa-accent), var(--rtmsa-frame));
  box-shadow: 0 3px 10px var(--rtmsa-shadow);
}
.rtmsa__main { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; align-items: flex-start; }
.rtmsa__name { margin: .1rem .25rem .32rem; color: var(--rtmsa-muted); font-size: .8em; font-weight: 600; }
.rtmsa__bubble {
  position: relative;
  max-width: min(100%, 36em);
  padding: .8em 1.15em;
  border: 1px solid var(--rtmsa-line);
  border-radius: 1.15rem;
  border-top-left-radius: .3rem;
  box-shadow: 0 4px 14px var(--rtmsa-shadow);
}
.rtmsa .rtmsa__bg { background: var(--rtmsa-bg-sheen), var(--rtmsa-panel); }
.rtmsa--user .rtmsa__bg { background: var(--rtmsa-bg-sheen), var(--rtmsa-panel-user); }
.rtmsa__footer { margin: .28rem .2rem 0; font-size: .82em; }
.rtmsa--user .rtmsa__row { flex-direction: row-reverse; }
.rtmsa--user .rtmsa__main { align-items: flex-end; }
.rtmsa--user .rtmsa__bubble { border-radius: 1.15rem; border-top-right-radius: .3rem; }
.rtmsa--user .rtmsa__footer { justify-content: flex-end; }
@media (max-width: 560px) { .rtmsa__bubble { max-width: 100%; } }

/* 짧은 대화: 맨 위 메시지 위쪽 빈 곳도 같은 바탕으로 칠합니다. */
.default-chat-screen > .risu-chat .rtmsa,
.chat-message-container:last-child .rtmsa { box-shadow: 0 -100vh 0 100vh var(--rtmsa-wall); }
/* 첫인사 위에 RisuAI가 붙이는 안내문(AI 생성 안내, 제작자 메모)이 칠한 바탕 아래로 숨지 않게 합니다. */
:where(.default-chat-screen > .risu-chat:has(.rtmsa) ~ *) { position: relative; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (남색) ── */
.rtmsa {
  --rtmsa-wall: #151b28;
  --rtmsa-panel: #1d2536;
  --rtmsa-panel-user: #242e42;
  --rtmsa-ink: #e2e6ed;
  --rtmsa-strong: #f6f8fc;
  --rtmsa-muted: #99a3b5;
  --rtmsa-accent: #c4aa6f;
  --rtmsa-dialog: #e7d39f;
  --rtmsa-frame: #2e3852;
  --rtmsa-shadow: rgba(0, 0, 0, .36);
  --rtmsa-line: #2c364f;
  --rtmsa-tint: #273149;
  --rtmsa-edit-bg: #19202f;
}
